	SHOWDOWNS_WAYPOINT_PORTAL = "Showdowns-portaal — Voidstorm",
	SHOWDOWNS_PORTAL_NOTE = "Portaal: de Voidstorm bij Screaming Ridge (51.4, 71.3), of het vaste portaal in de Bazaar van Silvermoon — zelfde verdieping als de weekly-quest-hub, iets verderop.",
	SHOWDOWNS_INFO_VAULT = "De weekly geeft een Riftstalker's Cache en telt mee voor je Great Vault-wereldrij.",
	SHOWDOWNS_INFO_HWT = "Heroic World Tier vereist geen unlock — kies Normal of Heroic bij het portaal.",
	TAB_PROF_ACADEMY = "Professions 101",
	INFO_DRAWER_BODY_PROFACADEMY = "Een beginnerscursus voor het Midnight-professionsysteem: wat Knowledge Points zijn, hoe je zonder spijt specialisatie-trees kiest, waar recepten vandaan komen en je wekelijkse routine. Elk hoofdstuk heeft een kleine praktijkopdracht — vink af terwijl je leert. Voortgang wordt per personage opgeslagen.",
	PROFACAD_SUBTITLE = "Professions voor beginners — wat Knowledge is, hoe je veilig trees kiest en je wekelijkse routine. Je eigen professies worden hieronder gedetecteerd; elke professie heeft een eigen starthoofdstuk, dat alleen verschijnt voor professies die je hebt.",
	PROFACAD_PROGRESS_FMT = "Voortgang: %d/%d hoofdstukken",
	PROFACAD_TASK_AUTO_HINT = "(vinkt zichzelf af zodra gedetecteerd)",
