	CONSREADY_BUFF = "buff",
	CONSREADY_BAG_UNKNOWN = "tas onbekend",
	CONSREADY_FOOTER = "|TInterface/RAIDFRAME/ReadyCheck-Ready:0|t aanwezig/actief · |TInterface/RAIDFRAME/ReadyCheck-NotReady:0|t ontbreekt · |TInterface/RAIDFRAME/ReadyCheck-Waiting:0|t onbekend. Van groepsleden zie je alleen de buff-status — de API kan niet in andermans tassen kijken (tas-delen komt in Fase 2). /mh readytoggle om te dempen.",
