	CONS_COPY_TT = "Klik: kopieer naam (voor het veilinghuis)",
	DELVE_SHARE_XLOC_HEADER_FMT = "%s deelde Delve-tips — hier in jouw taal:",
	PROFHUB_WEEKLY_HEADER = "Deze week",
	PROFHUB_WEEKLY_TRAINER = "trainer-weekly",
	PROFHUB_WEEKLY_ESSENCES = "Disenchant-mats in je tassen",
	PROFHUB_GOAL_LABEL = "Adviesdoel:",
	PROFHUB_GOAL_ALLROUND = "Allround",
	PROFHUB_GOAL_GOLD = "Goud",
	PROFHUB_GOAL_SELF = "Zelfvoorzienend",
	PROFHUB_GOAL_TT_ALLROUND = "De consensus-startroute: een gebalanceerde volgorde voor je eerste punten — degelijke craftkracht zonder je vast te leggen op een niche.",
	PROFHUB_GOAL_TT_GOLD = "Geeft voorrang aan trees waarvan de producten goed verkopen (enchants, flasks, bolt-cooldowns, geslepen gems). Kies dit als goud verdienen je doel is.",
	PROFHUB_GOAL_TT_SELF = "Geeft voorrang aan je eigen consumables en gear maken en zelfvoorziening in materialen, boven marktwaarde.",
