	INFO_DRAWER_BODY_CONSUMABLES = "Midnight Season 1 consumables per spec (Wowhead-lijst). Mijn character, < >, of zoeken (bv. havoc, beast) om een andere spec te bekijken zonder relog.",
	MACROS_MACRO_NAME_FMT = "%s",
	MACROS_COPY_SUFFIX = "Kopieer de tekst hieronder naar Esc > Macro's > Nieuw. Sleep daarna het macro-icoon naar een plek op je actiebalk (bijvoorbeeld 1, 2 of E).",
	MACROS_INTERRUPT_SUBTITLE = "Midnight-tip: Onderbreekt een cast met één druk op de knop. Kies hierboven een variant (Focus of Mouseover), lees de uitleg, en kopieer de tekst hieronder.",
	MACROS_INTERRUPT_VARIANT_FOCUS = "Focus",
	MACROS_INTERRUPT_VARIANT_MOUSEOVER = "Mouseover",
	MACROS_INTERRUPT_DESC_FOCUS = "Onderbreekt je focus als die een levende vijand is, anders je huidige target. Zet de gevaarlijke caster één keer op focus (/focus) en blijf gewoon je eigen target aanvallen — deze macro verandert of wist je focus nooit.",
	MACROS_INTERRUPT_DESC_MOUSEOVER = "Onderbreekt de vijand onder je muiscursor (werkt ook op nameplates en frames), anders je huidige target. Geen focus nodig: hover over de caster en druk.",
	MACROS_UTILITY_SUBTITLE = "Midnight-tip: Handige macro's voor je spec (cursor, mouseover, focus). Kies er een hierboven, lees de uitleg, en kopieer de tekst hieronder.",
	MACROS_ERR_NO_UTILITY = "Nog geen utility-macros voor deze spec.",
	MACROS_PANEL_SUBTITLE = "Midnight-tip: Onderbreekt een cast met een druk op de knop.\n\nEerst focus - zet de caster die je moet stoppen op focus en druk. Geen focus? De macro pakt een vijand in de buurt, onderbreekt, en zet je terug op wie je aanviel. Hij checkt niet alle mobs om je heen.\n\nKopieer de tekst hieronder naar Esc > Macro's > Nieuw. Sleep daarna het macro-icoon naar een plek op je actiebalk (bijvoorbeeld 1, 2 of E).",
	MACROS_ERR_NO_TYPE = "Dit macro-type is nog niet beschikbaar.",
